- И какое бы знамение из знамений их Господа ни приходило к ним, они отворачивались от него. (وَمَا تَأْتِيهِم مِّنْ آيَةٍ مِّنْ آيَاتِ رَبِّهِمْ إِلَّا كَانُوا عَنْهَا مُعْرِضِينَ) 6:4; 36:46
- И бойтесь того дня, когда ни одна душа не возместит другой нисколько, и не будет принято от неё заступничества. (وَاتَّقُوا يَوْمًا لَّا تَجْزِي نَفْسٌ عَن نَّفْسٍ شَيْئًا وَلَا يُقْبَلُ مِنْهَا) 2:48; 2:123
- Поистине, ты не можешь заставить мёртвых слышать и не можешь заставить глухих слышать призыв, когда они отворачиваются. (إِنَّكَ لَا تُسْمِعُ الْمَوْتَى وَلَا تُسْمِعُ الصُّمَّ الدُّعَاءَ إِذَا وَلَّوْا مُدْبِرِينَ) 27:80; 30:52
- Вам запрещено (есть) мертвечину, кровь, свинину и то, что было заколото с именем не Аллаха. (حُرِّمَتْ عَلَيْكُمُ الْمَيْتَةُ وَالدَّمُ وَلَحْمُ الْخِنزِيرِ وَمَا أُهِلَّ لِغَيْرِ اللَّهِ بِهِ) 5:3; 16:115
- Славит Аллаха всё, что в небесах и на земле, и Он – Всемогущий, Мудрый. (سَبَّحَ لِلَّهِ مَا فِي السَّمَاوَاتِ وَمَا فِي الْأَرْضِ وَهُوَ الْعَزِيزُ الْحَكِيمُ) 59:1; 61:1
- Кроме тех, кто после этого раскаялся и исправил (свои дела). Поистине, Аллах – Прощающий, Милосердный. (إِلَّا الَّذِينَ تَابُوا مِن بَعْدِ ذَلِكَ وَأَصْلَحُوا فَإِنَّ اللَّهَ غَفُورٌ رَّحِيمٌ) 3:89; 24:5
- (То, что) пророкам от их Господа; мы не делаем различия между ними, и мы Ему предавшиеся (мусульмане). (النَّبِيُّونَ مِن رَّبِّهِمْ لَا نُفَرِّقُ بَيْنَ أَحَدٍ مِّنْهُمْ وَنَحْنُ لَهُ مُسْلِمُونَ) 2:136; 3:84
- От твоего Господа (ниспослано), чтобы ты предостерегал народ, к которому до тебя не приходил предостерегатель, дабы они... (مِّن رَّبِّكَ لِتُنذِرَ قَوْمًا مَّا أَتَاهُم مِّن نَّذِيرٍ مِّن قَبْلِكَ لَعَلَّهُمْ) 28:46; 32:3
- О Пророк, борись с неверными и лицемерами и будь суров с ними. Их пристанище – ад (Джаханнам), и как же скверно это место! (يَا أَيُّهَا النَّبِيُّ جَاهِدِ الْكُفَّارَ وَالْمُنَافِقِينَ وَاغْلُظْ عَلَيْهِمْ وَمَأْوَاهُمْ جَهَنَّمُ وَبِئْسَ الْمَصِيرُ) 9:73; 66:9
- Поистине, твой Господь рассудит между ними в День Воскресения в том, в чём они расходились. (إِنَّ رَبَّكَ يَقْضِي بَيْنَهُمْ يَوْمَ الْقِيَامَةِ فِيمَا كَانُوا فِيهِ يَخْتَلِفُونَ) 10:93; 45:17
- Он сказал: Господи, сделай мне знамение. Он сказал: Твоё знамение в том, что ты не будешь говорить с людьми. (قَالَ رَبِّ اجْعَل لِّي آيَةً قَالَ آيَتُكَ أَلَّا تُكَلِّمَ النَّاسَ) 3:41; 19:10
- Обрати же лицо своё в сторону Заповедной Мечети. И где бы вы ни были, обращайте свои лица в её сторону. (فَوَلِّ وَجْهَكَ شَطْرَ الْمَسْجِدِ الْحَرَامِ وَحَيْثُ مَا كُنتُمْ فَوَلُّوا وُجُوهَكُمْ شَطْرَهُ) 2:144; 2:150
- О сыны Исраила, помните милость Мою, которую Я оказал вам, и то, что Я предпочёл вас мирам. (يَا بَنِي إِسْرَائِيلَ اذْكُرُوا نِعْمَتِيَ الَّتِي أَنْعَمْتُ عَلَيْكُمْ وَأَنِّي فَضَّلْتُكُمْ عَلَى الْعَالَمِينَ) 2:47; 2:122
- Семь тучных коров, которых съедают семь тощих; и семь зелёных колосьев и других сухих... (سَبْعَ بَقَرَاتٍ سِمَانٍ يَأْكُلُهُنَّ سَبْعٌ عِجَافٌ وَسَبْعَ سُنبُلَاتٍ خُضْرٍ وَأُخَرَ يَابِسَاتٍ) 12:43; 12:46
- И у каждой общины свой срок; когда наступает их срок, они не могут ни замедлить его на час, ни ускорить. (وَلِكُلِّ أُمَّةٍ أَجَلٌ فَإِذَا جَاءَ أَجَلُهُمْ لَا يَسْتَأْخِرُونَ سَاعَةً وَلَا يَسْتَقْدِمُونَ) 7:34; 10:49
- (То, что) заколото с именем не Аллаха, но если кто был вынужден (голодом), не будучи мятежным и не преступая границ, то... (أُهِلَّ لِغَيْرِ اللَّهِ بِهِ فَمَنِ اضْطُرَّ غَيْرَ بَاغٍ وَلَا عَادٍ فَإِنَّ) 6:145; 16:115
- И когда им говорят: Следуйте за тем, что ниспослал Аллах, они говорят: Нет, мы следуем за тем, на чём застали своих отцов. (وَإِذَا قِيلَ لَهُمُ اتَّبِعُوا مَا أَنزَلَ اللَّهُ قَالُوا بَلْ نَتَّبِعُ مَا) 2:170; 31:21
- Он сказал: О мой народ, поклоняйтесь Аллаху; нет у вас другого бога, кроме Него. Неужели вы не побоитесь (Его)? (قَالَ يَاقَوْمِ اعْبُدُوا اللَّهَ مَا لَكُم مِّنْ إِلَهٍ غَيْرُهُ أَفَلَا تَتَّقُونَ) 7:65; 23:23
