- Затем вы будете возвращены к Ведающему сокровенное и явное, и Он сообщит вам о том, что вы совершали. (ثُمَّ تُرَدُّونَ إِلَى عَالِمِ الْغَيْبِ وَالشَّهَادَةِ فَيُنَبِّئُكُم بِمَا كُنتُمْ تَعْمَلُونَ) 9:94; 62:8
