- Между ними в День воскресения будет рассуждено о том, в чём они расходились. (بَيْنَهُمْ يَوْمَ الْقِيَامَةِ فِيمَا كَانُوا فِيهِ يَخْتَلِفُونَ) 2:113; 10:93; 16:124; 22:69; 32:25; 45:17
- Разве они не странствовали по земле, чтобы увидеть, каков был конец? (أَوَلَمْ يَسِيرُوا فِي الْأَرْضِ فَيَنظُرُوا كَيْفَ كَانَ عَاقِبَةُ) 30:9; 35:44; 40:21; 40:82; 47:10
- Сады, где внизу текут реки, и они пребудут там вечно. (جَنَّاتٍ تَجْرِي مِن تَحْتِهَا الْأَنْهَارُ خَالِدِينَ فِيهَا أَبَدًا) 4:57; 4:122; 5:119; 64:9; 65:11
- Ты вводишь ночь в день и вводишь день в ночь. (تُولِجُ اللَّيْلَ فِي النَّهَارِ وَتُولِجُ النَّهَارَ فِي اللَّيْلِ) 3:27; 22:61; 31:29; 35:13; 57:6
- Прославляет Аллаха всё, что в небесах и на земле. (سَبَّحَ لِلَّهِ مَا فِي السَّمَاوَاتِ وَمَا فِي الْأَرْضِ) 59:1; 61:1; 62:1; 64:1
- Поклоняйтесь Аллаху, нет у вас иного бога, кроме Него. Неужели вы не устрашитесь? (اعْبُدُوا اللَّهَ مَا لَكُم مِّنْ إِلَهٍ غَيْرُهُ أَفَلَا) 7:65; 11:84; 23:23; 23:32
- И когда Мы сказали ангелам: Поклонитесь Адаму! – они поклонились, кроме Иблиса. (وَإِذْ قُلْنَا لِلْمَلَائِكَةِ اسْجُدُوا لِآدَمَ فَسَجَدُوا إِلَّا إِبْلِيسَ) 2:34; 17:61; 18:50; 20:116
- Аллах знает то, что в небесах и на земле. (اللَّهُ وَيَعْلَمُ مَا فِي السَّمَاوَاتِ وَمَا فِي الْأَرْضِ) 3:29; 5:97; 49:16; 58:7
- Сады, где внизу текут реки, и они пребудут там вечно, и это. (جَنَّاتٍ تَجْرِي مِن تَحْتِهَا الْأَنْهَارُ خَالِدِينَ فِيهَا وَذَلِكَ) 4:13; 5:85; 9:89; 57:12
- Его награда – у его Господа, и нет страха для них, и не будут они. (أَجْرُهُ عِندَ رَبِّهِ وَلَا خَوْفٌ عَلَيْهِمْ وَلَا هُمْ) 2:112; 2:262; 2:274; 2:277
- У его Господа, и нет страха для них, и они не будут опечалены. (عِندَ رَبِّهِ وَلَا خَوْفٌ عَلَيْهِمْ وَلَا هُمْ يَحْزَنُونَ) 2:112; 2:262; 2:274; 2:277
- Кто идёт прямым путём, тот идёт на пользу себе, а кто заблуждается. (فَمَنِ اهْتَدَى فَإِنَّمَا يَهْتَدِي لِنَفْسِهِ وَمَن ضَلَّ) 10:108; 17:15; 27:92
- Идёт на пользу себе, а кто заблуждается, тот заблуждается во вред себе. (يَهْتَدِي لِنَفْسِهِ وَمَن ضَلَّ فَإِنَّمَا يَضِلُّ عَلَيْهَا) 10:108; 17:15; 39:41
- Почему не ниспослано ему знамение от его Господа? Скажи: Поистине. (لَوْلَا أُنزِلَ عَلَيْهِ آيَةٌ مِّن رَّبِّهِ فَقُلْ إِنَّمَا) 10:20; 13:27; 29:50
- Тем, кто уверовал и творил добрые дела, – награда непреходящая. (الَّذِينَ آمَنُوا وَعَمِلُوا الصَّالِحَاتِ لَهُمْ أَجْرٌ غَيْرُ مَمْنُونٍ) 41:8; 84:25; 95:6
- Ты выводишь живое из мёртвого и выводишь мёртвое из живого. (وَتُخْرِجُ الْحَيَّ مِنَ الْمَيِّتِ وَتُخْرِجُ الْمَيِّتَ مِنَ الْحَيِّ) 3:27; 10:31; 30:19
- Кто не судит по тому, что ниспослал Аллах, те являются. (وَمَن لَّمْ يَحْكُم بِمَا أَنزَلَ اللَّهُ فَأُولَئِكَ هُمُ) 5:44; 5:45; 5:47
- Он создал небеса и землю и то, что между ними, в шесть дней. (خَلَقَ السَّمَاوَاتِ وَالْأَرْضَ وَمَا بَيْنَهُمَا فِي سِتَّةِ أَيَّامٍ) 25:59; 32:4; 50:38
- Воистину, Аллах милостив к людям, но большинство. (إِنَّ اللَّهَ لَذُو فَضْلٍ عَلَى النَّاسِ وَلَكِنَّ أَكْثَرَ) 2:243; 10:60; 40:61
- Аллах не был несправедлив к ним, но они сами были несправедливы к себе. (فَمَا كَانَ اللَّهُ لِيَظْلِمَهُمْ وَلَكِن كَانُوا أَنفُسَهُمْ يَظْلِمُونَ) 9:70; 29:40; 30:9
- Он простит вам грехи и введёт вас в сады, где внизу текут реки. (عَنكُمْ سَيِّئَاتِكُمْ وَلَأُدْخِلَنَّكُمْ جَنَّاتٍ تَجْرِي مِن تَحْتِهَا الْأَنْهَارُ) 5:12; 64:9; 66:8
- Он запретил вам мертвечину, кровь, мясо свиньи и то, что было заколото не во имя Аллаха. (حَرَّمَ عَلَيْكُمُ الْمَيْتَةَ وَالدَّمَ وَلَحْمَ الْخِنزِيرِ وَمَا أُهِلَّ) 2:173; 5:3; 16:115
- Я боюсь, если ослушаюсь моего Господа, наказания в Великий день. (إِنِّي أَخَافُ إِنْ عَصَيْتُ رَبِّي عَذَابَ يَوْمٍ عَظِيمٍ) 6:15; 10:15; 39:13
- Но после того, как к ним пришло знание, из зависти между ними. (إِلَّا مِن بَعْدِ مَا جَاءَهُمُ الْعِلْمُ بَغْيًا بَيْنَهُمْ) 3:19; 42:14; 45:17
- Они совершают молитву и раздают из того, чем Мы их наделили, тайно и открыто. (وَأَقَامُوا الصَّلَاةَ وَأَنفَقُوا مِمَّا رَزَقْنَاهُمْ سِرًّا وَعَلَانِيَةً) 13:22; 14:31; 35:29
- Неужели мы станем взывать помимо Аллаха к тому, что не приносит нам ни пользы, ни вреда? (مِن دُونِ اللَّهِ مَا لَا يَنفَعُنَا وَلَا يَضُرُّنَا) 6:71; 10:106; 25:55
- Они веруют в ниспосланное тебе и ниспосланное до тебя. (يُؤْمِنُونَ بِمَا أُنزِلَ إِلَيْكَ وَمَا أُنزِلَ مِن قَبْلِكَ) 2:4; 4:60; 4:162
- Разве ты не видишь, что Аллах ниспосылает с неба воду? (أَلَمْ تَرَ أَنَّ اللَّهَ أَنزَلَ مِنَ السَّمَاءِ مَاءً) 22:63; 35:27; 39:21
- Когда Он принимает решение, то говорит ему: Будь! – и оно становится. (قَضَى أَمْرًا فَإِنَّمَا يَقُولُ لَهُ كُن فَيَكُونُ) 3:47; 19:35; 40:68
- И к мадьянитам (Мы отправили) их брата Шуайба. Он сказал: О мой народ! Поклоняйтесь Аллаху. (وَإِلَى مَدْيَنَ أَخَاهُمْ شُعَيْبًا قَالَ يَاقَوْمِ اعْبُدُوا اللَّهَ) 7:85; 11:84; 29:36
- Это из вестей о сокровенном, которые Мы внушаем тебе; ты не знал этого. (ذَلِكَ مِنْ أَنْبَاءِ الْغَيْبِ نُوحِيهِ إِلَيْكَ وَمَا كُنتَ) 3:44; 11:49; 12:102
- Когда наступит их срок, они не смогут ни отложить его на час, ни приблизить. (فَإِذَا جَاءَ أَجَلُهُمْ لَا يَسْتَأْخِرُونَ سَاعَةً وَلَا يَسْتَقْدِمُونَ) 7:34; 10:49; 16:61
- Не следуйте по стопам сатаны, ведь он для вас – явный враг. (وَلَا تَتَّبِعُوا خُطُوَاتِ الشَّيْطَانِ إِنَّهُ لَكُمْ عَدُوٌّ مُّبِينٌ) 2:168; 2:208; 6:142
- Среди людей есть такие, которые спорят об Аллахе без всякого знания. (وَمِنَ النَّاسِ مَن يُجَادِلُ فِي اللَّهِ بِغَيْرِ عِلْمٍ) 22:3; 22:8; 31:20
- Аллах дарует это, кому пожелает, и Аллах – Обладатель великой милости. (اللَّهِ يُؤْتِيهِ مَن يَشَاءُ وَاللَّهُ ذُو الْفَضْلِ الْعَظِيمِ) 57:21; 57:29; 62:4
- Каждая душа получит сполна за то, что она приобрела, и не будут они обижены. (تُوَفَّى كُلُّ نَفْسٍ مَّا كَسَبَتْ وَهُمْ لَا يُظْلَمُونَ) 2:281; 3:25; 3:161
- Не убивайте душу, которую Аллах запретил, иначе как по праву. (وَلَا تَقْتُلُوا النَّفْسَ الَّتِي حَرَّمَ اللَّهُ إِلَّا بِالْحَقِّ) 6:151; 17:33; 25:68
- Когда Он принимает решение, то говорит ему: Будь! (إِذَا قَضَى أَمْرًا فَإِنَّمَا يَقُولُ لَهُ كُن) 3:47; 19:35; 40:68
- Войдите во врата Геенны, где пребудете вечно; и как скверно обиталище гордецов! (فَادْخُلُوا أَبْوَابَ جَهَنَّمَ خَالِدِينَ فِيهَا فَلَبِئْسَ مَثْوَى الْمُتَكَبِّرِينَ) 16:29; 39:72; 40:76
- Разве ты не видел тех, кому была дарована часть Писания? (أَلَمْ تَرَ إِلَى الَّذِينَ أُوتُوا نَصِيبًا مِّنَ الْكِتَابِ) 3:23; 4:44; 4:51
- Для них – сады, где внизу текут реки, и они пребудут там вечно. (لَهُمْ جَنَّاتٌ تَجْرِي مِن تَحْتِهَا الْأَنْهَارُ خَالِدِينَ فِيهَا) 3:198; 5:119; 9:89
- О мой народ! Действуйте по своему усмотрению, я тоже буду действовать, и скоро вы узнаете. (يَاقَوْمِ اعْمَلُوا عَلَى مَكَانَتِكُمْ إِنِّي عَامِلٌ فَسَوْفَ تَعْلَمُونَ) 6:135; 11:93; 39:39
- Кто противится Аллаху и Его Посланнику, для того – огонь Геенны, в котором он пребудет вечно. (اللَّهَ وَرَسُولَهُ فَأَنَّ لَهُ نَارَ جَهَنَّمَ خَالِدًا فِيهَا) 9:63; 72:23
- Мы наложили на их сердца покрывала, чтобы они не поняли его, и в их уши – глухоту. (عَلَى قُلُوبِهِمْ أَكِنَّةً أَن يَفْقَهُوهُ وَفِي آذَانِهِمْ وَقْرًا) 17:46; 18:57
- В какое бы селение Мы ни посылали увещевателя, его богатые жители говорили: Мы. (فِي قَرْيَةٍ مِّن نَّذِيرٍ إِلَّا قَالَ مُتْرَفُوهَا إِنَّا) 34:34; 43:23
- Они сказали: Попроси для нас твоего Господа, чтобы Он разъяснил нам, какова она. (قَالُوا ادْعُ لَنَا رَبَّكَ يُبَيِّن لَّنَا مَا هِيَ) 2:68; 2:70
- Они скажут: Аллах. Скажи: Хвала Аллаху! Но большинство их. (لَيَقُولُنَّ اللَّهُ قُلِ الْحَمْدُ لِلَّهِ بَلْ أَكْثَرُهُمْ لَا) 29:63; 31:25
- И ответ его народа был лишь таков: Изгоните их! (وَمَا كَانَ جَوَابَ قَوْمِهِ إِلَّا أَن قَالُوا أَخْرِجُوهُم) 7:82; 27:56
- Внизу которых текут реки, и они пребудут там вечно; это – великое преуспеяние. (تَحْتَهَا الْأَنْهَارُ خَالِدِينَ فِيهَا أَبَدًا ذَلِكَ الْفَوْزُ الْعَظِيمُ) 9:100; 64:9
- Они – на прямом пути от своего Господа, и они – преуспевшие. (أُولَئِكَ عَلَى هُدًى مِّن رَّبِّهِمْ وَأُولَئِكَ هُمُ الْمُفْلِحُونَ) 2:5; 31:5
- Тот, кого постигнет унизительное наказание и кого постигнет вечное наказание. (مَن يَأْتِيهِ عَذَابٌ يُخْزِيهِ وَيَحِلُّ عَلَيْهِ عَذَابٌ مُّقِيمٌ) 11:39; 39:40
- Странствуйте по земле и смотрите, каков был конец тех, кто считал ложью. (فَسِيرُوا فِي الْأَرْضِ فَانظُرُوا كَيْفَ كَانَ عَاقِبَةُ الْمُكَذِّبِينَ) 3:137; 16:36
- Они никогда не пожелают этого из-за того, что совершили их руки, и Аллах знает несправедливых. (يَتَمَنَّوْهُ أَبَدًا بِمَا قَدَّمَتْ أَيْدِيهِمْ وَاللَّهُ عَلِيمٌ بِالظَّالِمِينَ) 2:95; 62:7
- Он лучше знает, кто сбился с Его пути, и Он лучше знает. (هُوَ أَعْلَمُ بِمَن ضَلَّ عَن سَبِيلِهِ وَهُوَ أَعْلَمُ) 53:30; 68:7
- Аллах – мой Господь и ваш Господь, поклоняйтесь же Ему; это – прямой путь. (إِنَّ اللَّهَ رَبِّي وَرَبُّكُمْ فَاعْبُدُوهُ هَذَا صِرَاطٌ مُّسْتَقِيمٌ) 3:51; 19:36
- Он милостив к людям, но большинство их неблагодарны. (لَذُو فَضْلٍ عَلَى النَّاسِ وَلَكِنَّ أَكْثَرَهُمْ لَا يَشْكُرُونَ) 10:60; 27:73
- Небеса и земля и то, что между ними, Мы создали только по истине и на определённый срок. (السَّمَاوَاتِ وَالْأَرْضَ وَمَا بَيْنَهُمَا إِلَّا بِالْحَقِّ وَأَجَلٍ مُّسَمًّى) 30:8; 46:3
- Оставь их погружаться (в пустословие) и забавляться, пока они не встретят свой день, который им обещан. (فَذَرْهُمْ يَخُوضُوا وَيَلْعَبُوا حَتَّى يُلَاقُوا يَوْمَهُمُ الَّذِي يُوعَدُونَ) 43:83; 70:42
- Когда они встречают тех, кто уверовал, они говорят: Мы уверовали, а когда остаются наедине. (وَإِذَا لَقُوا الَّذِينَ آمَنُوا قَالُوا آمَنَّا وَإِذَا خَلَوْا) 2:14; 2:76
- Они соблюдают Тору, Евангелие и то, что ниспослано им от их Господа. (أَقَامُوا التَّوْرَاةَ وَالْإِنجِيلَ وَمَا أُنزِلَ إِلَيْهِم مِّن رَّبِّهِمْ) 5:66; 5:68
- Он знает то, что перед ними, и то, что позади них, а они не объемлют этого знанием. (يَعْلَمُ مَا بَيْنَ أَيْدِيهِمْ وَمَا خَلْفَهُمْ وَلَا يُحِيطُونَ) 2:255; 20:110
- Он – Тот, кто создал небеса и землю за шесть дней. (وَهُوَ الَّذِي خَلَقَ السَّمَاوَاتِ وَالْأَرْضَ فِي سِتَّةِ أَيَّامٍ) 11:7; 57:4
- В этом – знамение для вас, если вы верующие. (إِنَّ فِي ذَلِكَ لَآيَةً لَّكُمْ إِن كُنتُم مُّؤْمِنِينَ) 2:248; 3:49
- Что же помешало людям уверовать, когда к ним пришло руководство? (وَمَا مَنَعَ النَّاسَ أَن يُؤْمِنُوا إِذْ جَاءَهُمُ الْهُدَى) 17:94; 18:55
- Они приравнивали к Аллаху сотоварищей, чтобы сбивать с Его пути. Скажи: Наслаждайтесь. (وَجَعَلُوا لِلَّهِ أَندَادًا لِّيُضِلُّوا عَن سَبِيلِهِ قُلْ تَمَتَّعُوا) 14:30; 39:8
- Они удивились, что к ним пришёл увещеватель из них самих, и неверующие сказали: Это. (وَعَجِبُوا أَن جَاءَهُم مُّنذِرٌ مِّنْهُمْ وَقَالَ الْكَافِرُونَ هَذَا) 38:4; 50:2
- Твой Господь лучше знает, кто сбился с Его пути. (إِنَّ رَبَّكَ هُوَ أَعْلَمُ بِمَن ضَلَّ عَن سَبِيلِهِ) 53:30; 68:7
- Подобен тому, кто расходует своё имущество напоказ людям и не верует в Аллаха. (كَالَّذِي يُنفِقُ مَالَهُ رِئَاءَ النَّاسِ وَلَا يُؤْمِنُ بِاللَّهِ) 2:264; 4:38
- Расходуйте из того, чем Мы вас наделили, прежде чем наступит. (أَنفِقُوا مِمَّا رَزَقْنَاكُم مِّن قَبْلِ أَن يَأْتِيَ) 2:254; 63:10
- Он подчинил вам то, что в небесах, и то, что на земле. (سَخَّرَ لَكُم مَّا فِي السَّمَاوَاتِ وَمَا فِي الْأَرْضِ) 31:20; 45:13
- Мы в сомнении относительно того, к чему ты нас призываешь. (وَإِنَّنَا لَفِي شَكٍّ مِّمَّا تَدْعُونَا إِلَيْهِ مُرِيبٍ) 11:62; 14:9
- Твой Господь увеличивает удел, кому пожелает, и ограничивает. Поистине, Он. (إِنَّ رَبَّكَ يَبْسُطُ الرِّزْقَ لِمَن يَشَاءُ وَيَقْدِرُ إِنَّهُ) 17:30; 34:36
- Господь небес и земли и того, что между ними, если вы убеждены. (رَبُّ السَّمَاوَاتِ وَالْأَرْضِ وَمَا بَيْنَهُمَا إِن كُنتُم مُّوقِنِينَ) 26:24; 44:7
- Мы уверовали в Аллаха и в ниспосланное нам, и в ниспосланное. (آمَنَّا بِاللَّهِ وَمَا أُنزِلَ إِلَيْنَا وَمَا أُنزِلَ إِلَى) 2:136; 3:199
- И тех, кто был несправедлив, постиг ужасный вопль, и они оказались в своих домах бездыханными. (وَأَخَذَ الَّذِينَ ظَلَمُوا الصَّيْحَةُ فَأَصْبَحُوا فِي دِيَارِهِمْ جَاثِمِينَ) 11:67; 11:94
- Нет на вас греха в том, что они делают в отношении себя. (فَلَا جُنَاحَ عَلَيْكُمْ فِيمَا فَعَلْنَ فِي أَنفُسِهِنَّ) 2:234; 2:240
- Твой Господь лучше знает, кто сбился с Его пути, и Он. (رَبَّكَ هُوَ أَعْلَمُ بِمَن ضَلَّ عَن سَبِيلِهِ وَهُوَ) 53:30; 68:7
- С Духом (откровением) по Своему повелению на того, кого пожелает из Своих рабов. (بِالرُّوحِ مِنْ أَمْرِهِ عَلَى مَن يَشَاءُ مِنْ عِبَادِهِ) 16:2; 40:15
- Мы даровали Исе, сыну Марьям, ясные знамения и укрепили его Святым Духом. (وَآتَيْنَا عِيسَى ابْنَ مَرْيَمَ الْبَيِّنَاتِ وَأَيَّدْنَاهُ بِرُوحِ الْقُدُسِ) 2:87; 2:253
- Чтобы Он рассудил между ними в День воскресения о том, в чём они расходились. (لَيَحْكُمُ بَيْنَهُمْ يَوْمَ الْقِيَامَةِ فِيمَا كَانُوا فِيهِ) 16:124; 22:69
- Мы перевернули город вверх дном и пролили на них дождь из камней обожжённой глины. (جَعَلْنَا عَالِيَهَا سَافِلَهَا وَأَمْطَرْنَا عَلَيْهَا حِجَارَةً مِّن سِجِّيلٍ) 11:82; 15:74
- Для них одинаково – будешь ли ты их увещевать или не будешь, – они не уверуют. (سَوَاءٌ عَلَيْهِمْ أَأَنذَرْتَهُمْ أَمْ لَمْ تُنذِرْهُمْ لَا يُؤْمِنُونَ) 2:6; 36:10
- Кроме людей, пожелайте смерти, если вы правдивы. (مِّن دُونِ النَّاسِ فَتَمَنَّوُا الْمَوْتَ إِن كُنتُمْ صَادِقِينَ) 2:94; 62:6
- Аллаха, нет у вас иного бога, кроме Него. Неужели вы не устрашитесь? (اللَّهَ مَا لَكُم مِّنْ إِلَهٍ غَيْرُهُ أَفَلَا تَتَّقُونَ) 23:23; 23:32
- Если Мы покажем тебе часть того, что обещаем им, или если Мы умертвим тебя, – к Нам их возвращение. (وَإِمَّا نُرِيَنَّكَ بَعْضَ الَّذِي نَعِدُهُمْ أَوْ نَتَوَفَّيَنَّكَ فَإِلَيْنَا) 10:46; 40:77
- Они сказали: Неужели, когда мы умрём и станем прахом и костями, мы будем воскрешены? (قَالُوا أَإِذَا مِتْنَا وَكُنَّا تُرَابًا وَعِظَامًا أَإِنَّا لَمَبْعُوثُونَ) 23:82; 56:47
- Милость – в руке Аллаха, Он дарует её, кому пожелает, и Аллах. (إِنَّ الْفَضْلَ بِيَدِ اللَّهِ يُؤْتِيهِ مَن يَشَاءُ وَاللَّهُ) 3:73; 57:29
- И вы будете возвращены к Ведающему сокровенное и явное, и Он сообщит вам о том, что вы совершали. (إِلَى عَالِمِ الْغَيْبِ وَالشَّهَادَةِ فَيُنَبِّئُكُم بِمَا كُنتُمْ تَعْمَلُونَ) 9:105; 62:8
- О вы, которые уверовали! Помните милость Аллаха к вам, когда. (يَا أَيُّهَا الَّذِينَ آمَنُوا اذْكُرُوا نِعْمَتَ اللَّهِ عَلَيْكُمْ إِذْ) 5:11; 33:9
- Мы отправляли до тебя только мужей, которым внушали откровение. (وَمَا أَرْسَلْنَا مِن قَبْلِكَ إِلَّا رِجَالًا نُّوحِي إِلَيْهِم) 12:109; 16:43
- Он простит ему грехи и введёт его в сады, где внизу текут реки. (يُكَفِّرْ عَنْهُ سَيِّئَاتِهِ وَيُدْخِلْهُ جَنَّاتٍ تَجْرِي مِن تَحْتِهَا) 64:9; 66:8
- Кто болен или находится в пути, то (следует поститься) другие дни. (مَّرِيضًا أَوْ عَلَى سَفَرٍ فَعِدَّةٌ مِّنْ أَيَّامٍ أُخَرَ) 2:184; 2:185
- Они следуют лишь предположениям, и они лишь измышляют. (إِن يَتَّبِعُونَ إِلَّا الظَّنَّ وَإِنْ هُمْ إِلَّا يَخْرُصُونَ) 6:116; 10:66
- Прекрасный пример для тех, кто надеется на Аллаха и Последний день. (أُسْوَةٌ حَسَنَةٌ لِّمَن كَانَ يَرْجُو اللَّهَ وَالْيَوْمَ الْآخِرَ) 33:21; 60:6
- Мы не создали небеса и землю и то, что между ними, иначе как по истине. (وَمَا خَلَقْنَا السَّمَاوَاتِ وَالْأَرْضَ وَمَا بَيْنَهُمَا إِلَّا بِالْحَقِّ) 15:85; 46:3
- Вложи свою руку за пазуху, она выйдет белой, без всякого зла. (يَدَكَ فِي جَيْبِكَ تَخْرُجْ بَيْضَاءَ مِنْ غَيْرِ سُوءٍ) 27:12; 28:32
- Он избирает своей милостью, кого пожелает, и Аллах – Обладатель великой милости. (يَخْتَصُّ بِرَحْمَتِهِ مَن يَشَاءُ وَاللَّهُ ذُو الْفَضْلِ الْعَظِيمِ) 2:105; 3:74
- Разве ты не знаешь, что Аллаху принадлежит власть над небесами и землёй? (أَلَمْ تَعْلَمْ أَنَّ اللَّهَ لَهُ مُلْكُ السَّمَاوَاتِ وَالْأَرْضِ) 2:107; 5:40
- Что бы вы ни сделали добра для себя, вы найдёте это у Аллаха. (وَمَا تُقَدِّمُوا لِأَنفُسِكُم مِّنْ خَيْرٍ تَجِدُوهُ عِندَ اللَّهِ) 2:110; 73:20
- И откуда бы ты ни вышел, обращай лицо в сторону Заповедной мечети. (وَمِنْ حَيْثُ خَرَجْتَ فَوَلِّ وَجْهَكَ شَطْرَ الْمَسْجِدِ الْحَرَامِ) 2:149; 2:150
- Те, кто были до вас, – и ты не найдёшь изменения в установлении Аллаха. (خَلَوْا مِن قَبْلُ وَلَن تَجِدَ لِسُنَّةِ اللَّهِ تَبْدِيلًا) 33:62; 48:23
- Тот, Кому принадлежит то, что в небесах и на земле. (الَّذِي لَهُ مَا فِي السَّمَاوَاتِ وَمَا فِي الْأَرْضِ) 34:1; 42:53
- Ни одна женщина не беременеет и не рожает, иначе как с Его ведома. (وَمَا تَحْمِلُ مِنْ أُنثَى وَلَا تَضَعُ إِلَّا بِعِلْمِهِ) 35:11; 41:47
- Он подчинил ночь, солнце и луну; всё движется до определённого срока. (اللَّيْلِ وَسَخَّرَ الشَّمْسَ وَالْقَمَرَ كُلٌّ يَجْرِي لِأَجَلٍ مُّسَمًّى) 35:13; 39:5
- Внизу которых текут реки, и они пребудут там вечно, и это – награда. (تَجْرِي مِن تَحْتِهَا الْأَنْهَارُ خَالِدِينَ فِيهَا وَذَلِكَ جَزَاءُ) 5:85; 20:76
- Он сказал: Нет, ваши души внушили вам нечто; но терпение – прекрасно. (قَالَ بَلْ سَوَّلَتْ لَكُمْ أَنفُسُكُمْ أَمْرًا فَصَبْرٌ جَمِيلٌ) 12:18; 12:83
- То, что в небесах и на земле, и что Аллах. (مَا فِي السَّمَاوَاتِ وَمَا فِي الْأَرْضِ وَأَنَّ اللَّهَ) 5:97; 22:64
- И какой бы посланник ни приходил к ним, они насмехались над ним. (وَمَا يَأْتِيهِم مِّن رَّسُولٍ إِلَّا كَانُوا بِهِ يَسْتَهْزِئُونَ) 15:11; 36:30
- Они сказали: О Муса! Бросишь ли ты, или мы бросим? (قَالُوا يَامُوسَى إِمَّا أَن تُلْقِيَ وَإِمَّا أَن نَّكُونَ) 7:115; 20:65
- Он усыпляет вас (смертью), и некоторых из вас возвращает в самую унизительную старость, чтобы. (يَتَوَفَّاكُمْ وَمِنكُم مَّن يُرَدُّ إِلَى أَرْذَلِ الْعُمُرِ لِكَيْ) 16:70; 22:5
- Для них – у их Господа – сады, где внизу текут реки, и они пребудут там вечно. (رَبِّهِمْ جَنَّاتٌ تَجْرِي مِن تَحْتِهَا الْأَنْهَارُ خَالِدِينَ فِيهَا) 3:15; 3:136
- И Мы наложили на их сердца покрывала, чтобы они не поняли его, и в их уши – глухоту. (وَجَعَلْنَا عَلَى قُلُوبِهِمْ أَكِنَّةً أَن يَفْقَهُوهُ وَفِي آذَانِهِمْ) 17:46; 18:57
- Обещание Аллаха истинно, но большинство их не знает. (إِنَّ وَعْدَ اللَّهِ حَقٌّ وَلَكِنَّ أَكْثَرَهُمْ لَا يَعْلَمُونَ) 10:55; 28:13
- Это за то, что они противились Аллаху и Его Посланнику; а кто противится Аллаху. (ذَلِكَ بِأَنَّهُمْ شَاقُّوا اللَّهَ وَرَسُولَهُ وَمَن يُشَاقِقِ اللَّهَ) 8:13; 59:4
- В тот день, когда Он призовёт их и скажет: Где же те, кого вы считали Моими сотоварищами? (وَيَوْمَ يُنَادِيهِمْ فَيَقُولُ أَيْنَ شُرَكَائِيَ الَّذِينَ كُنتُمْ تَزْعُمُونَ) 28:62; 28:74
- Разве они не видели, что Аллах, создавший небеса и землю, способен создать подобных им? (أَوَلَمْ يَرَوْا أَنَّ اللَّهَ الَّذِي خَلَقَ السَّمَاوَاتِ وَالْأَرْضَ) 17:99; 46:33
- (Тот), кто создал вас из земли, потом из капли, потом. (بِالَّذِي خَلَقَكَ مِن تُرَابٍ ثُمَّ مِن نُّطْفَةٍ ثُمَّ) 18:37; 40:67
- Они сказали бы: Господь наш! Почему Ты не отправил к нам посланника, чтобы мы последовали за Твоими знамениями? (لَقَالُوا رَبَّنَا لَوْلَا أَرْسَلْتَ إِلَيْنَا رَسُولًا فَنَتَّبِعَ آيَاتِكَ) 20:134; 28:47
- Затем их возвращение – к их Господу, и Он сообщит им о том, что они совершали. (ثُمَّ إِلَى رَبِّهِم مَّرْجِعُهُمْ فَيُنَبِّئُهُم بِمَا كَانُوا يَعْمَلُونَ) 6:108; 39:7
- Нет у них знания об этом; они следуют лишь предположениям. (مَّا لَهُم بِذَلِكَ مِنْ عِلْمٍ إِنْ هُمْ إِلَّا) 43:20; 45:24
- Мы нашли своих отцов на этом пути, и мы идём по их следам. (إِنَّا وَجَدْنَا آبَاءَنَا عَلَى أُمَّةٍ وَإِنَّا عَلَى آثَارِهِم) 43:22; 43:23
- Те, кому было даровано Писание, разошлись лишь после того, как к ним пришло знание. (الَّذِينَ أُوتُوا الْكِتَابَ إِلَّا مِن بَعْدِ مَا جَاءَهُمُ) 3:19; 98:4
- И когда Ибрахим сказал: Господь мой! Сделай этот город безопасным. (وَإِذْ قَالَ إِبْرَاهِيمُ رَبِّ اجْعَلْ هَذَا بَلَدًا آمِنًا) 2:126; 14:35
- Он даровал вам слух, зрение и сердца; но мало вы благодарны. (وَجَعَلَ لَكُمُ السَّمْعَ وَالْأَبْصَارَ وَالْأَفْئِدَةَ قَلِيلًا مَّا تَشْكُرُونَ) 32:9; 67:23
- Те, кто препираются о знамениях Аллаха без всякого довода, который бы пришёл к ним. (الَّذِينَ يُجَادِلُونَ فِي آيَاتِ اللَّهِ بِغَيْرِ سُلْطَانٍ أَتَاهُمْ) 40:35; 40:56
- Так следуйте же религии Ибрахима, будучи единобожниками, и он не был из многобожников. (فَاتَّبِعُوا مِلَّةَ إِبْرَاهِيمَ حَنِيفًا وَمَا كَانَ مِنَ الْمُشْرِكِينَ) 3:95; 16:123
- И когда Мы спасли вас от рода Фараона, который подвергал вас ужасным мучениям. (وَإِذْ أَنجَيْنَاكُم مِّنْ آلِ فِرْعَوْنَ يَسُومُونَكُمْ سُوءَ الْعَذَابِ) 7:141; 14:6
- Это – прямая религия, но большинство людей не знает. (ذَلِكَ الدِّينُ الْقَيِّمُ وَلَكِنَّ أَكْثَرَ النَّاسِ لَا يَعْلَمُونَ) 12:40; 30:30
- Разве ты не видишь, что Аллах подчинил вам то, что в. (أَلَمْ تَرَ أَنَّ اللَّهَ سَخَّرَ لَكُم مَّا فِي) 22:65; 31:20
- Неверующие сказали бы: Это – не что иное, как явное колдовство. (لَقَالَ الَّذِينَ كَفَرُوا إِنْ هَذَا إِلَّا سِحْرٌ مُّبِينٌ) 6:7; 11:7
- И когда им читают Наши ясные знамения, неверующие говорят. (وَإِذَا تُتْلَى عَلَيْهِمْ آيَاتُنَا بَيِّنَاتٍ قَالَ الَّذِينَ كَفَرُوا) 19:73; 46:7
- Сады вечности, где внизу текут реки, и они пребудут там вечно. (جَنَّاتُ عَدْنٍ تَجْرِي مِن تَحْتِهَا الْأَنْهَارُ خَالِدِينَ فِيهَا) 20:76; 98:8
- Он творит, что пожелает; Аллах над всякой вещью мощен. (مَا يَشَاءُ إِنَّ اللَّهَ عَلَى كُلِّ شَيْءٍ قَدِيرٌ) 24:45; 35:1
- Чтобы Он простил вам грехи и отсрочил вас до определённого срока. (لِيَغْفِرَ لَكُم مِّن ذُنُوبِكُمْ وَيُؤَخِّرَكُمْ إِلَى أَجَلٍ مُّسَمًّى) 14:10; 71:4
- Хотите ли вы отвратить нас от того, чему поклонялись наши отцы? (تُرِيدُونَ أَن تَصُدُّونَا عَمَّا كَانَ يَعْبُدُ آبَاؤُنَا) 14:10; 34:43
- И когда твой Господь сказал ангелам: Я создам человека из глины. (وَإِذْ قَالَ رَبُّكَ لِلْمَلَائِكَةِ إِنِّي خَالِقٌ بَشَرًا مِّن) 15:28; 38:71
- Он – Тот, кто посылает ветры как благие вести перед Своей милостью. (وَهُوَ الَّذِي يُرْسِلُ الرِّيَاحَ بُشْرًا بَيْنَ يَدَيْ رَحْمَتِهِ) 7:57; 25:48
- Скажи: Странствуйте по земле и смотрите, каков был конец. (قُلْ سِيرُوا فِي الْأَرْضِ فَانظُرُوا كَيْفَ كَانَ عَاقِبَةُ) 27:69; 30:42
- В сотворении небес и земли и в смене ночи и дня (есть знамения). (إِنَّ فِي خَلْقِ السَّمَاوَاتِ وَالْأَرْضِ وَاخْتِلَافِ اللَّيْلِ وَالنَّهَارِ) 2:164; 3:190
- Кто тот, кто одолжит Аллаху прекрасный заём, чтобы Он умножил его? (مَّن ذَا الَّذِي يُقْرِضُ اللَّهَ قَرْضًا حَسَنًا فَيُضَاعِفَهُ) 2:245; 57:11
- Суди между ними по тому, что ниспослал Аллах, и не следуй за их страстями. (فَاحْكُم بَيْنَهُم بِمَا أَنزَلَ اللَّهُ وَلَا تَتَّبِعْ أَهْوَاءَهُمْ) 5:48; 5:49
- Неужели они ждут чего-то иного, кроме как прихода к ним ангелов или прихода твоего Господа? (هَلْ يَنظُرُونَ إِلَّا أَن تَأْتِيَهُمُ الْمَلَائِكَةُ أَوْ يَأْتِيَ) 6:158; 16:33
- Те, кто возводит на Аллаха ложь, не преуспеют. (إِنَّ الَّذِينَ يَفْتَرُونَ عَلَى اللَّهِ الْكَذِبَ لَا يُفْلِحُونَ) 10:69; 16:116
- По примеру рода Фараона и тех, кто был до них; они сочли ложью Наши знамения. (كَدَأْبِ آلِ فِرْعَوْنَ وَالَّذِينَ مِن قَبْلِهِمْ كَذَّبُوا بِآيَاتِنَا) 3:11; 8:54
- И он радует верующих, которые творят добрые дела, что для них – награда. (وَيُبَشِّرُ الْمُؤْمِنِينَ الَّذِينَ يَعْمَلُونَ الصَّالِحَاتِ أَنَّ لَهُمْ أَجْرًا) 17:9; 18:2
- Аллах увеличивает удел, кому пожелает из Своих рабов, и ограничивает. (اللَّهَ يَبْسُطُ الرِّزْقَ لِمَن يَشَاءُ مِنْ عِبَادِهِ وَيَقْدِرُ) 28:82; 29:62
- И вы будете возвращены к Ведающему сокровенное и явное, и Он сообщит вам о том, что вы совершали. (وَسَتُرَدُّونَ إِلَى عَالِمِ الْغَيْبِ وَالشَّهَادَةِ فَيُنَبِّئُكُم بِمَا كُنتُمْ) 9:105; 62:8
- И кровные родственники ближе друг к другу в Писании Аллаха. (وَأُولُو الْأَرْحَامِ بَعْضُهُمْ أَوْلَى بِبَعْضٍ فِي كِتَابِ اللَّهِ) 8:75; 33:6
cmds - Commands, Exhortations, Prohibitions, Instructions
- fard / wajib (فرض / واجب) — обязательный (необходимо выполнять; грех пропускать)
- mustahabb / mandub (مستحب / مندوب) — рекомендуемый (награда за выполнение, нет греха за пропуск)
- mubah (مباح) — нейтральный / дозволенный (нет ни награды, ни греха)
- makruh (مكروه) — неодобряемый (не рекомендуется, но греха нет, если совершено)
- haram (حرام) — запретный (грех совершать)
- halal (حلال, дозволенное / законное) — охватывает и мубах, и мустахабб — всё, что не запрещено
- Поклоняйтесь одному Аллаху и просите помощи у Него. 1:5
- Поклоняйтесь одному Аллаху 2:21
- Не приобщайте Аллаху сотоварищей 2:22
- Аллах — Тот, Кто прощает (принимает покаяние), Он принял покаяние Адама (عَلَيْهِ ٱلسَّلَامُ). 2:37
- Не смешивайте истину с ложью и не скрывайте истину. 2:42
- Совершайте намаз (ежедневные молитвы) и давайте закят (милостыню). 2:43
- Приказывайте добродетель другим, только после того как сами будете её практиковать 2:44
- Ищите помощи Аллаха во всех ваших делах 2:45
- Не участвуйте в распространении нечестия и не распространяйте его 2:60
- Не препятствуйте людям посещать места поклонения 2:114
- Уважайте святость мечети. Содержите ваши молитвенные места в чистоте 2:125
- Помните Аллаха (молитвой, прославлением и т.д.), и Он вспомнит вас, и будьте благодарны Ему. 2:152
- Проявляйте терпение в трудностях 2:153
- Не следуйте по стопам Шайтана (Сатаны), который является явным врагом. 2:168
- Не следуйте слепо за кем-либо 2:170
- Храните и выполняйте все поручения. Исполняйте свои религиозные обязанности искренне. Выполняйте свои клятвы и обещания. Соблюдайте обещания, особенно данные Аллаху. Поддерживайте нуждающихся и облегчайте трудности. Избегайте совершения грехов, которые ведут к лишению Божьей милости. Не позволяйте гордыне вести вас к несправедливости 2:177
- В возмездии (кисас) для вас — жизнь. 2:179
- Поститесь в месяц Рамадан. Соблюдайте предписанный пост, чтобы стать богобоязненными. 2:183
- Уважайте Коран как высший источник руководства 2:185
- Не пожирайте имущество друг друга незаконно и не давайте взятки судьям (перед представлением ваших дел). 2:188
- Не угнетайте других, ни словом, ни делом. Никогда не вступайте в сражения как агрессоры, но только для защиты 2:190
- Защищайте сирот. Что касается сирот, честно распоряжайтесь их имуществом и не пожирайте их имущество. 2:220
- Кайтесь и просите прощения у Аллаха. Не вступайте в половую близость во время менструации. Соблюдайте чистоту (как физическую, так и духовную) 2:222
- Выполняйте свои обязанности перед семьёй 2:233
- Выбирайте лидеров по их заслугам 2:247
- Нет принуждения в религии 2:256
- Тратьте имущество на благотворительность. Будьте щедры как имуществом, так и временем 2:261
- Не сводите на нет благотворительность, хвастаясь своей щедростью 2:264
- Шайтан (Сатана) угрожает вам бедностью и приказывает вам совершать мерзости (грехи). 2:268
- Ищите нуждающихся и помогайте им 2:273
- Не занимайтесь ростовщичеством или процентами. Не потребляйте имущество, основанное на процентах. Не ешьте рибу (ростовщичество). 2:275
- Дайте должнику больше времени для выплаты, если он в трудном положении 2:280
- Держите слово в деловых сделках. Будьте честны в ваших финансовых делах. Действуйте с честностью во всех ваших обязательствах. Заключая договор займа на определённый срок, записывайте его. Берите свидетелей, когда заключаете торговый контракт. 2:282
- Храните и выполняйте все поручения 2:283
- Верьте в ниспосланные Книги и всех пророков 2:285
- Аллах не возлагает на душу сверх её возможностей. Она получит награду за то (добро), что приобрела, и понесёт наказание за то (зло), что приобрела. Бог не возлагает на человека сверх его возможностей; и нам не следует делать этого. Доверяйте плану Аллаха даже в трудностях 2:286
- Кто выполняет обещания и боится Аллаха, то, поистине, Аллах любит богобоязненных. 3:76
- Совершайте хадж (паломничество), если вы в состоянии 3:97
- Не разделяйтесь 3:103
- Приказывайте одобряемое и запрещайте порицаемое. Поощряйте праведность в вашем сообществе. Призывайте других к поминанию Аллаха 3:104
- На Аллаха должны полагаться верующие. 3:122
- Не ешьте рибу (ростовщичество). 3:130
- Повинуйтесь Аллаху и Его Посланнику, чтобы обрести милость. 3:132
- Аллах любит тех, кто расходует (на дела Аллаха — благотворительность, подаяние и т.д.) в благополучии и в трудностях, кто сдерживает гнев и прощает людям. 3:134
- Сдерживайте гнев. 3:134
- Прощайте ошибки других 3:135
- Не будьте грубы в речи. Будьте терпеливы с теми, кто не согласен с вами 3:159
- Если Аллах поможет вам, никто не одолеет вас; а если Он оставит вас, то кто же после Него поможет вам? 3:160
- Каждый вкусит смерть. И только в День Воскресения вы получите вашу плату сполна. 3:185
- Глубоко размышляйте о чудесах природы и творении этой вселенной. Знайте, что Бог создал вселенную со смыслом и целью 3:191
- Мужчины и женщины имеют равную награду за свои дела 3:195
- Для тех, кто боится своего Господа, — сады, в которых текут реки (в Раю); они пребудут там вечно, как угощение от Аллаха. 3:198
- Всегда стремитесь к довольству Аллаха в каждом действии. 3:200
- Будьте почтительны к вашему Господу, бойтесь Его и (не разрывайте связей) с родственниками. 4:1
- Отдавайте сиротам их имущество и не меняйте (ваши) дурные вещи на (их) хорошие; и не пожирайте их имущество (присоединяя его) к вашему. 4:2
- Давайте женщинам (за которых вы выходите замуж) их махр (обязательный брачный дар, который муж даёт жене при заключении брака) от всей души. 4:4
- Защищайте права сирот 4:6
- Имущество умершего должно быть распределено между членами его семьи. Женщины имеют право на наследство 4:7
- Не пожирайте незаконно имущество сирот 4:10
- Соблюдайте предписания о наследстве 4:11
- Запрещено наследовать женщин против их воли и обращаться с ними сурово. Живите с ними (жёнами) достойно. Уважайте и соблюдайте права женщин. Относитесь к своему супругу с добротой и состраданием. Относитесь к женщинам с честью и справедливостью 4:19
- Не женитесь на тех, кто связан с вами кровным родством 4:23
- Не убивайте самих себя (и не убивайте друг друга). Поистине, Аллах милостив к вам. Не пожирайте имущество друг друга незаконно 4:29
- Если вы избегаете больших грехов, которые запрещены, Аллах простит вам ваши (малые) грехи и введёт вас в благородный вход (т.е. Рай). 4:31
- Не желайте того, в чём Аллах дал преимущество одним из вас перед другими. Избегайте зависти и ревности 4:32
- Мужчины являются попечителями и содержателями женщин, потому что Аллах дал одним преимущество перед другими, и потому что они расходуют из своего имущества (на их содержание). Мужчина — защитник и опора семьи 4:34
- Поклоняйтесь Аллаху и не приобщайте Ему сотоварищей, делайте добро родителям, родственникам, сиротам, беднякам, соседу, товарищу, находящемуся рядом с вами, путнику и тем (невольникам), которыми владеют ваши десницы. Аллах не любит тех, кто горд и хвастлив. Будьте добры к другим. Проявляйте милосердие к слабым. Поддерживайте родственные связи и почитайте родственников. 4:36
- Не будьте скупыми 4:37
- Аллах не прощает приобщения Ему сотоварищей в поклонении, но прощает всё остальное (кроме этого) кому пожелает. 4:48
- Не завидуйте другим 4:54
- Аллах повелевает вам возвращать вверенное вам имущество его владельцам. Когда вы судите между людьми, судите по справедливости. 4:58
- Повинуйтесь Аллаху и Его Посланнику. Оказывайте должное уважение тем, кто обладает властью среди вас 4:59
- Не угнетайте слабых и уязвимых 4:75
- Всё доброе, что приходит к вам, — от Аллаха, а всё злое, что постигает вас, — от вас самих. 4:79
- Тот, кто повинуется Посланнику (Мухаммаду ﷺ), тот повиновался Аллаху. 4:80
- Кто ходатайствует за доброе дело, тот получит долю награды за него; а кто ходатайствует за злое дело, тот получит долю его бремени. 4:85
- Не подобает верующему убивать другого верующего, иначе как по ошибке. 4:92
- Тот, кто умышленно убивает верующего, воздаянием ему будет Геенна, в которой он пребудет вечно. На него гнев и проклятие Аллаха, и для него уготовано великое наказание. 4:93
- Тот, кто переселится (из своего дома) на пути Аллаха, найдёт на земле много убежищ и изобилие. 4:100
- Будьте пунктуальны в своих молитвах 4:103
- Не поддерживайте и не будьте адвокатами для тех, кто предаёт вверенное им 4:105
- Просите прощения у Аллаха, поистине, Аллах — Прощающий, Милосердный. 4:106
- О те, которые уверовали! Стойте твёрдо за справедливость, будучи свидетелями ради Аллаха, даже если это будет против вас самих, или ваших родителей, или родственников, будь он богат или беден. Не откладывайте правосудие; действуйте незамедлительно, исправляя несправедливость 4:135
- Лицемеры хотят обмануть Аллаха, но это Аллах обманывает их. 4:142
- Лицемеры будут в самом низу (степени) Огня; и не найдёшь ты для них помощника. 4:145
- Аллах не любит, чтобы зло произносилось вслух, кроме как теми, кто был обижен. 4:148
- (Мы отправили) посланников как благовестников и предостерегателей, чтобы у людей не было оправдания перед Аллахом после (прихода) посланников. 4:165
- Выполняйте свои контракты и обещания 5:1
- Помогайте друг другу в благочестии и богобоязненности, но не в грехе и вражде 5:2
- Не употребляйте в пищу мертвечину, кровь животных и свинину 5:3
- Будьте справедливы; пусть вражда и ненависть других не удерживают вас от справедливости. Будьте справедливы и честны в своих делах. Знайте, что справедливость близка к богобоязненности. Не откладывайте правосудие; действуйте незамедлительно, исправляя несправедливость 5:8
- Ищите средства приближения к Аллаху и усердствуйте на Его пути, сколько можете, чтобы вы преуспели. 5:35
- Выполняйте свои клятвы и обещания 5:89
- Избегайте опьяняющих напитков и алкоголя. Строго избегайте опьяняющих напитков (всех видов спиртных напитков), азартных игр, идолов и стрел для гадания, которые являются мерзостью из деяний Шайтана (Сатаны). 5:90
- Не убивайте дичь, когда вы находитесь в состоянии ихрама для хаджа или умры (паломничества). 5:95
- Не спрашивайте о вещах, которые, если будут вам разъяснены, могут причинить вам беспокойство. 5:101
- Не оскорбляйте божества других людей. Не оскорбляйте тех, кого они (неверные) призывают помимо Аллаха, чтобы они не оскорбили Аллаха по невежеству. 6:108
- Если вы будете повиноваться большинству тех, кто на земле, они введут вас в заблуждение на пути Аллаха. Они следуют только предположениям и только измышляют ложь. 6:116
- Оставьте (о, люди!) все виды греха, явного и скрытого. 6:120
- Не ешьте (о, верующие!) из того (мяса), над которым не было произнесено имя Аллаха (при заклании). 6:121
- Кого Аллах желает наставить на прямой путь, того Он раскрывает грудь для Ислама; а кого желает ввести в заблуждение, того Он делает грудь сжатой и тесной. 6:125
- Будьте умеренны в расходах и избегайте расточительства. Соблюдайте права всех творений 6:141
- Не приобщайте сотоварищей в поклонении Аллаху, будьте добры к родителям, не убивайте своих детей из страха бедности, не приближайтесь к мерзостям, не убивайте никого, кого Аллах запретил, кроме как по праву. 6:151
- Будьте честны; не обманывайте ни в каких сделках. Не приближайтесь к имуществу сироты, кроме как для его улучшения, давайте полную меру и вес по справедливости; когда вы даёте слово, говорите правду, даже если это касается близкого родственника; и выполняйте завет с Аллахом. 6:152
- Следуйте прямым путём и не следуйте (другими) путями, ибо они отделят вас от Его пути. 6:153
- Скажи (о, Мухаммад ﷺ): «Воистину, моя молитва, моё жертвоприношение, моя жизнь и моя смерть — ради Аллаха, Господа миров». 6:162
- Не будьте высокомерными 7:13
- Пусть Шайтан (Сатана) не обманет вас. 7:27
- Скажи (о, Мухаммад ﷺ): «Мой Господь повелел справедливость...» 7:29
- Соблюдайте пределы, установленные Аллахом, во всех делах. Избегайте преступлений в речи и действиях. Ешьте и пейте, но не будьте чрезмерны. Носите хорошую одежду во время молитвы 7:31
- Аллах создал небеса и землю за шесть дней, а затем утвердился на Троне (так, как подобает Его Величию). 7:54
- Взывайте к своему Господу со смирением и в тайне. Он не любит преступающих границы. 7:55
- И не творите бесчинства на земле после того, как она приведена в порядок, и взывайте к Нему со страхом и надеждой. 7:56
- Но те, которые совершали злые дела, а затем покаялись и уверовали, — поистине, твой Господь после этого — Прощающий, Милосердный. 7:153
- Скажи (о, Мухаммад ﷺ): «О, люди! Воистину, я — Посланник Аллаха ко всем вам...» 7:158
- И (все) прекрасные имена принадлежат Аллаху, поэтому взывайте к Нему через них и оставьте тех, кто отрицает или хулит Его имена... 7:180
- Кого Аллах вводит в заблуждение, тому нет наставника; и Он оставляет их скитаться вслепую в своём произволе. 7:186
- Проявляйте снисходительность, приказывайте добро и отворачивайтесь от невежд (то есть не наказывайте их). 7:199
- Прощайте другим их ошибки 7:199
- А если тебя коснётся наваждение от Шайтана (Сатаны), то ищи убежища у Аллаха. Поистине, Он — Слышащий, Знающий. 7:200
- Верующими являются только те, у которых при упоминании Аллаха сердца испытывают страх, а когда читаются им Его аяты, они усиливают в них веру... 8:2
- Не предавайте Аллаха и Его Посланника и не предавайте намеренно ваши аманаты (то, что вам вверено, и все обязанности, которые Аллах предписал вам). 8:27
- Если вы будете повиноваться Аллаху и бояться Его, Он дарует вам различение (между истиной и ложью). 8:29
- Те, которые не веруют, расходуют своё имущество, чтобы отвратить (людей) от пути Аллаха, и они будут продолжать расходовать его; но в конце концов это станет для них скорбью. 8:36
- Скажите тем, кто не уверовал, что если они прекратят (неверие), то их прошлое будет прощено. Но если они вернутся (к нему), то примеры (наказания) тех, кто жил до них, уже были даны (в назидание). 8:38
- Когда вы встречаете (силы врага), стойте твёрдо и поминайте имя Аллаха много (и языком, и сердцем), чтобы вы преуспели. 8:45
- Не будьте подобны тем, которые вышли из своих домов с гордостью и напоказ людям и отвращают (людей) от пути Аллаха. 8:47
- Аллах не меняет милости, которую Он даровал народу, пока они не изменят того, что в их душах. 8:53
- Наихудшие из живых существ пред Аллахом — те, которые не веруют. 8:55
- Бог вкладывает любовь и привязанность между сердцами тех, кто верует в Него 8:63
- Защищайте и помогайте тем, кто ищет защиты 9:6
- Не подобает многобожникам содержать мечети Аллаха. 9:17
- Они (неверные, иудеи и христиане) хотят погасить свет Аллаха (с которым был послан Мухаммад ﷺ — исламский единобожие) своими устами, но Аллах не допустит, чтобы Его свет не был совершен, даже если это ненавистно неверным. 9:32
- Садака (т.е. закят) предназначены только: 1) для бедных, 2) для неимущих, 3) для тех, кто занят их сбором, 4) для привлечения сердец тех, кто склоняется к Исламу, 5) для освобождения рабов, 6) для должников, 7) для дела Аллаха (т.е. для моджахедов) и 8) для путников. 9:60
- Тот, кто враждует с Аллахом и Его Посланником (ﷺ), для того, поистине, адский огонь, в котором он пребудет вечно. Это величайшее унижение. 9:63
- Лицемеры, мужчины и женщины, — они подобны друг другу. Они забыли Аллаха, и Он забыл их. 9:67
- Стремитесь к чистоте. Уважайте святость мечети 9:108
- Не подобает Пророку и верующим просить прощения у Аллаха для многобожников, даже если они родственники, после того как им стало ясно, что они обитатели Огня (потому что умерли в состоянии неверия). 9:113
- Кто же несправедливее того, кто возводит на Аллаха ложь или отрицает Его аяты? Поистине, грешники никогда не преуспеют! 10:17
- Они поклоняются помимо Аллаха тому, что не причиняет им вреда и не приносит пользы, и говорят: «Это наши заступники перед Аллахом». Скажи: «Разве вы сообщаете Аллаху то, чего Он не знает на небесах и на земле?» Пречист Он и превыше того, что они приобщают Ему в сотоварищи! 10:18
- Воздаянием за зло является равное ему зло. 10:27
- Таков Аллах, ваш истинный Господь. Что же после истины может быть, кроме заблуждения? Как же вы отвращены? 10:32
- Большинство из них следует только предположениям. Поистине, предположения никак не могут заменить истину. 10:36
- Поистине, Аллах не поступает несправедливо с людьми; но люди сами поступают несправедливо с собой. 10:44
- Знайте, что даяние Бога лучше всего, что человек может накопить или собрать 10:58
- Не будь из тех, кто отрицает аяты Аллаха, иначе ты окажешься в числе потерпевших убыток. 10:95
- Если Аллах коснётся тебя вредом, никто не сможет удалить его, кроме Него; а если Он пожелает тебе добра, никто не сможет отвратить Его щедрости, которую Он дарует тому из Своих рабов, кому пожелает. 10:107
- Нет ни одного живого существа на земле, пропитание которого не зависело бы от Аллаха. И Он знает место его стоянки и место его упокоения (в утробе, могиле и т.д.). 11:6
- Если Мы дадим человеку вкусить милости от Нас, а затем отнимем её у него, он становится отчаявшимся, неблагодарным. 11:9
- Кто желает жизни в этом мире и его украшений, тем Мы полностью воздадим за их дела в нём, и они не будут обделены. 11:15
- Мы не были несправедливы к ним, но они сами были несправедливы к себе. И те божества, которых они призывали помимо Аллаха, ничуть не помогли им, когда пришло повеление твоего Господа, и не добавили им ничего, кроме гибели. 11:101
- В тот день, когда он настанет, никто не заговорит без дозволения Аллаха. Среди них будут и несчастные, и (другие) блаженные. 11:105
- Что касается несчастных, то они будут в Огне, издавая стоны и рыдания. 11:106
- Они пребудут там всё время, пока существуют небеса и земля, если только твой Господь не пожелает иначе. Поистине, твой Господь творит то, что пожелает. 11:107
- А те, которые блаженны, будут в Раю, пребывая там всё время, пока существуют небеса и земля, если только твой Господь не пожелает иначе, как дар бесконечный. 11:108
- Не склоняйтесь на сторону тех, кто поступает несправедливо, чтобы Огонь не коснулся вас, и не будет у вас покровителей, кроме Аллаха, и тогда вы не будете помилованы. 11:113
- Совершайте намаз на обоих концах дня и в некоторые часы ночи (т.е. пять обязательных молитв). Добрые дела удаляют злые дела (т.е. малые грехи). 11:114
- Аллаху принадлежит сокровенное знание небес и земли, и к Нему возвращаются все дела (для решения). 11:123
- Решение принадлежит только Аллаху. Он повелел поклоняться только Ему (единобожие), это и есть прямая религия, но большинство людей не знает. 12:40
- Никогда не теряйте надежды на милость Аллаха 12:87
- И большинство людей не уверуют, даже если вы будете страстно желать этого. 12:103
- И большинство из них не верует в Аллаха, иначе как приобщая Ему сотоварищей (т.е. они многобожники). 12:106
- Это (Коран) — не вымышленное изречение, а подтверждение того, что было до него (Таурат, Инджиль и другие Писания), и подробное разъяснение всего, и руководство, и милость для людей верующих. 12:111
- Аллах увеличивает пропитание для тех, кого пожелает, и ограничивает (его для тех, кого пожелает). 13:26
- Часто поминайте Аллаха через зикр. Те, кто верует в Бога, обретают удовлетворение в поминании Его. 13:28
- Те, которые уверовали и творят добро, — им радость и покой души. 13:29
- Те, кто предпочитает жизнь в этом мире жизни будущей и отвращает (людей) от пути Аллаха (Ислама) и ищет в нём кривизны, — те находятся в глубоком заблуждении. 14:3
- Проявляйте смирение и благодарность в поклонении 14:7
- Притча о тех, кто не верует в своего Господа: дела их подобны пеплу, над которым сильно подул ветер в бурный день; они не смогут получить ничего из того, что они приобрели. 14:18
- Аллах укрепляет тех, кто уверовал, твёрдым словом в этой жизни (т.е. они будут поклоняться одному Аллаху и никому другому) и в жизни будущей. 14:27
- Не думайте, что Аллах не ведает о том, что творят несправедливые (многобожники и т.д.), но Он даёт им отсрочку до того дня, когда глаза будут вытаращены от ужаса. 14:42
- Чтобы Аллах воздал каждой душе за то, что она приобрела. Поистине, Аллах скор в расчёте. 14:51
- И воистину, Мы создали человека из сухой звонкой глины, из изменённой чёрной грязи. 15:26
- А джиннов Мы создали до того из палящего огня. 15:27
- У него (Ада) семь врат, для каждых врат предназначена своя (особая) группа (грешников). 15:44
- Он создал человека из капли семени, и вот он становится явным противником. 16:4
- И скот Он создал для вас; в нём есть тепло (тёплая одежда) и много пользы, и вы им питаетесь. 16:5
- И (создал) коней, мулов и ослов, чтобы вы на них ездили и как украшение. И Он создаёт (другие) вещи, о которых вы не знаете. 16:8
- Он — Тот, Кто ниспосылает с неба воду; вы пьёте из неё, и благодаря ей произрастает растительность, на которой вы пасёте скот. 16:10
- Он — Тот, Кто подчинил вам море, чтобы вы ели из него свежее мясо (рыбу) и извлекали из него украшения, которые вы носите. 16:14
- Он установил на земле незыблемые горы, чтобы она не колебалась вместе с вами, а также реки и дороги, чтобы вы могли идти прямым путём. 16:15
- Разве Тот, кто творит, подобен тому, кто не творит? Неужели вы не помяните? 16:17
- Если вы попытаетесь сосчитать милости Аллаха, вам их не счесть. 16:18
- Аллах знает то, что вы скрываете, и то, что вы обнародуете. 16:19
- Те, кого они (многобожники) призывают помимо Аллаха, не создали ничего, но сами были созданы. 16:20
- (Они) мертвы, безжизненны и не ведают, когда будут воскрешены. 16:21
- Когда Мы желаем чего-либо, Наше слово заключается лишь в том, что Мы говорим ему: «Будь!» — и оно бывает. 16:40
- Неужели те, кто строит злые козни, не уверены, что Аллах не заставит землю поглотить их или что наказание не постигнет их оттуда, откуда они не ожидают? 16:45
- Всё, что вы имеете из благ, — от Аллаха. И когда вас постигает беда, вы взываете к Нему о помощи. 16:53
- Затем, когда Он удаляет беду от вас, часть из вас начинает приобщать сотоварищей к своему Господу (Аллаху). 16:54
- В скоте для вас — назидание. Мы поим вас тем, что у них в животах, между калом и кровью, чистым молоком, приятным для пьющих. 16:66
- Не приводите Аллаху подобий (ибо ничто не подобно Ему, и Он ни на что не похож). Поистине, Аллах знает, а вы не знаете. 16:74
- Знайте, что Бог дал человеку слух, зрение, разум и чувства, чтобы они были благодарны 16:78
- Избегайте жадности и алчности 16:97
- Когда вы хотите читать Коран, ищите убежища у Аллаха от Шайтана (Сатаны), изгнанного (проклятого). 16:98
- Знайте, что несправедливость, совершённая по невежеству, прощается, если человек покается и исправится 16:119
- Призывай (о, Мухаммад ﷺ) на путь твоего Господа (Ислам) с мудростью и добрым наставлением, и веди спор с ними наилучшим образом. Призыв других на путь Бога должен совершаться с мудростью и добротой 16:125
- Аллах с теми, кто боится Его (исполняет свои обязанности перед Ним), и с теми, кто творит добро. 16:128
- Этот Коран ведёт к самому справедливому и прямому пути. 17:9
- Никто не понесёт чужого бремени (грехов). 17:15
- Кто желает жизни будущей и стремится к ней надлежащим образом, будучи верующим, то такие — их усердие будет оценено, вознаграждено и принято (Аллахом). 17:19
- Почитайте своих родителей и относитесь к ним с добротой. Будьте почтительны к родителям. Не говорите им грубого слова. И Господь твой предписал не поклоняться никому, кроме Него, и делать добро родителям. Если один из них или оба достигнут старости в твоей жизни, не говори им грубого слова и не кричи на них, а обращайся к ним с уважением. 17:23
- И склони пред ними крыло смирения и милосердия и скажи: «Господи! Помилуй их, ведь они растили меня, когда я был маленьким». 17:24
- Поистине, расточители — братья дьяволов, а дьявол неблагодарен своему Господу. 17:27
- Не расточай деньги 17:29
- Не убивайте своих детей из страха бедности 17:31
- Не прелюбодействуйте. Соблюдайте святость брака и избегайте прелюбодеяния 17:32
- Давайте полную меру, когда вы отмериваете, и взвешивайте на правильных весах. Это лучше и лучше по исходу. 17:35
- Не следуй (о, человек, т.е. не говори, не делай и не свидетельствуй и т.п.) тому, чего ты не знаешь (например, когда кто-то говорит: «Я видел», хотя он не видел, или «Я слышал», хотя он не слышал). 17:36
- Будьте смиренны и не будьте высокомерны. Не ходи по земле горделиво. Поистине, ты не сможешь ни разорвать землю, ни достигнуть высоты гор. 17:37
- Твой Господь лучше всех знает тебя: если Он захочет, помилует тебя, а если захочет, накажет тебя. 17:54
- Кто слеп в этой жизни (т.е. не видит знамений Аллаха и не верует в Него), тот будет слеп и в будущей жизни и ещё более заблудшим на пути. 17:72
- Соблюдайте установленное время для молитвы 17:78
- Воистину, Мы разъяснили людям в этом Коране всевозможные притчи, но большинство людей отвергают (истину и не принимают ничего), кроме неверия. 17:89
- Мы привели в этом Коране людям всевозможные притчи. Но человек более спорщик, чем что-либо. 18:54
- Воздаянием им будет Геенна (Ад), потому что они не уверовали и насмехались над Моими аятами и Моими посланниками. 18:106
- Не подобает Аллаху (по Его Величию) иметь сына (это относится к клевете христиан на Аллаха, что Иисус — сын Аллаха). Пречист Он (и превыше того, что они приобщают Ему в сотоварищи). 19:35
- Говорите с людьми мягко 20:44
- Соревнуйтесь друг с другом в совершении добра 21:90
- Избегайте пустых разговоров 23:3
- Оберегайте свою скромность 23:5
- Оберегайте своё сердце от греховных склонностей 23:97
- Прощайте других и прощайте их ошибки 24:22
- Уважайте частную жизнь других, особенно в их собственных домах. Выполняйте права соседей 24:27
- Опускайте взор (как мужчинам, так и женщинам). Оберегайте свою скромность и целомудрие. 24:30
- Соблюдайте скромность в одежде и поведении 24:31
- Знайте, что Бог дарует безопасность и мир тем, кто поклоняется Ему и поступает праведно 24:55
